// Korean Pokémon cards.
//
// Why this exists: TCGdex serves Korean card METADATA (names, numbers, sets) but
// ZERO Korean card IMAGES — its assets.tcgdex.net/ko/ paths all 404 — and Korea
// gets its own sets rather than localised editions of the Western ones. The old
// embedding catalog therefore skipped every Korean set, and Korean scanning fell
// back to the English catalog, which cannot see Korea-exclusive cards.
//
// The catalog is now BUNDLED. `shared/pokemonKoreaCatalog.json` (generated by
// scripts/fetch-korea-catalog.mjs from tcgexchange.kr) holds all 271 Korean sets
// and ~20k cards — set code, number, English name, Korean name, rarity and image
// URL — so Korean search and scanning work with no download, no API key and no
// network at runtime. The live API is kept only as a fallback when the bundled
// file is missing (e.g. a dev checkout that has not run the generator).
//
// IDs: `tcgexchange-kr-<setCode>-<number>` (e.g. `tcgexchange-kr-SV4K-001`).
// The prefix routes through cardApi without touching pokemonProvider policy.
const fs = require('fs');
const path = require('path');
const axios = require('axios');
const db = require('./db');
const { cacheNormalizedCards } = require('./utils/cardCache');
const { parseCardRow } = require('./utils/priceHelpers');
const languages = require('./utils/languages');

const BASE = 'https://api.tcgexchange.kr/v1';
const PREFIX = 'tcgexchange-kr-';
const LANG = 'kr';
const BUNDLE_PATH = path.join(__dirname, '..', '..', 'shared', 'pokemonKoreaCatalog.json');

const client = axios.create({
  baseURL: BASE,
  timeout: 30000,
  headers: { Accept: 'application/json', 'User-Agent': `Bindarr/${require('../package.json').version}` },
});

// tcgexchange set codes are ALREADY the provider's own (SV4K, SM1M, ...), so the
// id is the set code itself. cardId() adds the prefix.
const cardId = (setId, number) => `${PREFIX}${setId}-${number}`;
const providerId = (id) => String(id || '').replace(new RegExp(`^${PREFIX}`), '');

// Split `tcgexchange-kr-SV4K-001` back into set code and number.
function splitId(id) {
  const rest = providerId(id);
  const m = rest.match(/^(.+)-(\d+)$/);
  return m ? { setId: m[1], number: m[2] } : { setId: rest, number: '' };
}

// A tcgexchange card -> the card_cache shape.
//
// `name` = English name (searchable from any language); `printed_name` = Korean
// (what's on the card). Same two-name contract as Scryfall/TCGdex.
function normalizeCard(card, setName, setCode) {
  const code = languages.toCode('ko');
  const name = card.name || '';
  const printedName = card.name_ko || name;
  return {
    id: cardId(setCode || card.set_code, card.number),
    name,
    printed_name: printedName,
    supertype: card.species || '',       // tcgexchange has species, not supertype
    subtypes: [],
    types: [],
    rarity: card.rarity || 'Common',
    set_id: setCode || card.set_code || '',
    set_name: setName || card.set_name || '',
    number: String(card.number ?? ''),
    image_url: card.image_url || '',
    game: 'pokemon',
    language: languages.toName(code),
    price_trend: null,                   // tcgexchange has no prices; TCGCSV can fill later
    price_normal: null,
    price_holofoil: null,
    price_reverse_holofoil: null,
    price_avg1: null, price_avg7: null, price_avg30: null,
    price_currency: null,
    price_source: null,
    cmc: null,
    color_identity: [],
    tcgplayer_url: null,
    cardmarket_url: null,
  };
}

const sameNumber = (a, b) => {
  const x = String(a || '').replace(/^0+/, '');
  const y = String(b || '').replace(/^0+/, '');
  return x === y;
};

// --- Bundled catalog -----------------------------------------------------
//
// Cards are stored as arrays ([setCode, number, name, name_ko, rarity, image])
// because 20k rows of repeated JSON keys is several MB of pure overhead. The
// index below turns them into the provider's card shape on demand.
let bundle = null;
let bundleTried = false;
let index = null;

function loadBundle() {
  if (bundleTried) return bundle;
  bundleTried = true;
  try {
    const parsed = JSON.parse(fs.readFileSync(BUNDLE_PATH, 'utf8'));
    if (Array.isArray(parsed.sets) && Array.isArray(parsed.cards)) bundle = parsed;
  } catch { bundle = null; }
  return bundle;
}

function ensureIndex() {
  if (index || !loadBundle()) return index;
  const sets = bundle.sets.map(s => ({
    id: s.code,
    name: s.name,
    name_ko: s.name_ko || '',
    series: s.era || '',
    printed_total: s.printedTotal || 0,
    total: s.cardCount || 0,
    release_date: s.releaseDate || '',
    ptcgo_code: '',
    symbol_url: s.symbol || '',
    logo_url: s.logo || '',
    game: 'pokemon',
  }));
  const byCode = new Map(sets.map(s => [s.id.toLowerCase(), s]));
  const cards = new Map();   // lower-cased set code -> array of raw rows
  for (const row of bundle.cards) {
    const key = String(row[0] || '').toLowerCase();
    let bucket = cards.get(key);
    if (!bucket) { bucket = []; cards.set(key, bucket); }
    bucket.push(row);
  }
  index = { sets, byCode, cards };
  return index;
}

const rowToCard = (i, r) => normalizeCard(
  { name: r[2], name_ko: r[3], number: r[1], rarity: r[4], image_url: r[5], set_code: r[0] },
  (i.byCode.get(String(r[0] || '').toLowerCase()) || {}).name,
  r[0]
);

// --- Live API fallback ---------------------------------------------------

async function liveListSets() {
  const { data } = await client.get('/catalog/sets', { params: { language: LANG } });
  return (data?.sets || [])
    // A handful of legacy sets (6 of 277) have no set_code upstream — they cannot
    // be addressed by /sets/{id}/cards. Skip them rather than let a null id reach
    // card_cache.
    .filter(s => s.set_code)
    .map(s => ({
      id: s.set_code,
      name: s.name,
      series: s.era || '',
      printed_total: s.printed_total || 0,
      total: s.card_count || 0,
      release_date: String(s.release_date || '').replace(/-/g, '/'),
      ptcgo_code: '',
      symbol_url: s.symbol_url || '',
      logo_url: s.logo_url || '',
      game: 'pokemon',
    }));
}

async function liveGetCardsBySet(setCode) {
  const wanted = String(setCode || '').toLowerCase();
  const { data } = await client.get('/catalog/sets', { params: { language: LANG } });
  const set = (data?.sets || []).find(s => String(s.set_code || '').toLowerCase() === wanted);
  if (!set) return [];
  const { data: cd } = await client.get(`/catalog/sets/${encodeURIComponent(set.id)}/cards`);
  return (cd?.cards || []).map(c => normalizeCard(c, set.name, set.set_code));
}

// --- Public interface ----------------------------------------------------

async function listSets(lang = 'ko') {
  const i = ensureIndex();
  if (i) return i.sets;
  return liveListSets();
}

async function getCardsBySet(setCode, lang = 'ko') {
  const i = ensureIndex();
  if (i) {
    const rows = i.cards.get(String(setCode || '').toLowerCase()) || [];
    return rows.map(r => rowToCard(i, r));
  }
  return liveGetCardsBySet(setCode);
}

// searchCards: match the other providers' interface so routes/collection.js can
// call it without a language branch.
async function searchCards({ name = '', number = '', set = '', lang = 'ko', limit = 60, page = 1 } = {}) {
  const code = languages.toCode(lang);
  if (code !== 'ko') return { cards: [], total: null };

  const i = ensureIndex();
  if (i) {
    const wanted = String(set).split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
    const nName = String(name).toLowerCase();
    const rows = bundle.cards.filter(r => {
      if (wanted.length && !wanted.includes(String(r[0] || '').toLowerCase())) return false;
      if (number && !sameNumber(r[1], number)) return false;
      if (nName && !(String(r[2] || '').toLowerCase().includes(nName)
        || String(r[3] || '').toLowerCase().includes(nName))) return false;
      return true;
    });
    const offset = (page - 1) * limit;
    return {
      cards: rows.slice(offset, offset + limit).map(r => rowToCard(i, r)),
      total: rows.length,
    };
  }

  // Set-scoped search reads the whole set in one request (same pattern as TCGdex).
  if (set) {
    const setCodes = String(set).split(',').map(s => s.trim()).filter(Boolean);
    const all = [];
    for (const sc of setCodes) {
      const cards = await liveGetCardsBySet(sc).catch(() => []);
      all.push(...cards);
    }
    const filtered = all.filter(c =>
      (!number || sameNumber(c.number, number)) &&
      (!name || c.name.toLowerCase().includes(name.toLowerCase()) ||
        c.printed_name.toLowerCase().includes(name.toLowerCase()))
    );
    const offset = (page - 1) * limit;
    return { cards: filtered.slice(offset, offset + limit), total: filtered.length };
  }

  // Name-only search: walk sets until enough matches (bounded).
  if (name) {
    const sets = await liveListSets().catch(() => []);
    const matches = [];
    for (const s of sets) {
      if (matches.length >= limit * page) break;
      const cards = await liveGetCardsBySet(s.id).catch(() => []);
      const hit = cards.filter(c =>
        (!number || sameNumber(c.number, number)) &&
        (c.name.toLowerCase().includes(name.toLowerCase()) ||
          c.printed_name.toLowerCase().includes(name.toLowerCase()))
      );
      matches.push(...hit);
    }
    const offset = (page - 1) * limit;
    return { cards: matches.slice(offset, offset + limit), total: matches.length };
  }

  return { cards: [], total: null };
}

async function getCardById(id) {
  const cached = await db.get(`SELECT * FROM card_cache WHERE id = ?`, [id]);
  if (cached) return parseCardRow(cached);
  const { setId, number } = splitId(id);
  if (!setId || !number) return null;
  const cards = await getCardsBySet(setId).catch(() => []);
  const card = cards.find(c => sameNumber(c.number, number));
  if (card) await cacheNormalizedCards([card], 'pokemon');
  return card || null;
}

// Find the Korean printing of a card by its English name (and number when known).
// Used by the scan route to turn a vision identity into the Korean card.
async function findPrinting(name, number = '') {
  if (!name) return null;
  const { cards } = await searchCards({ name, number, lang: 'ko', limit: 25 });
  if (!cards.length) return null;
  // An exact number match wins; otherwise the first (the caller shows a picker).
  if (number) {
    const exact = cards.find(c => sameNumber(c.number, number));
    if (exact) return exact;
  }
  return cards[0];
}

// Fetch-and-cache sets into the `sets` table (called from server.js at boot).
async function fetchAndCacheSets(force = false) {
  try {
    const existing = await db.get(`SELECT COUNT(*) n FROM sets WHERE game = 'pokemon' AND id LIKE ?`, [`${PREFIX}%`]);
    // tcgexchange set ids are already bare (SV4K); prefix them in the table so
    // they don't collide with TCGdex ids (sv4k vs SV4K are the same set).
    if (!force && existing && existing.n > 0) {
      console.log(`Korean sets already populated (${existing.n}). Skipping.`);
      return;
    }
    const fromBundle = !!ensureIndex();
    console.log(`Loading Korean sets ${fromBundle ? 'from the bundled catalog' : 'from tcgexchange.kr'}...`);
    const sets = await listSets('ko');
    if (!sets.length) throw new Error('no Korean sets available');
    for (const s of sets) {
      await db.run(
        `INSERT OR REPLACE INTO sets (id, name, series, printed_total, total, release_date, ptcgo_code, symbol_url, logo_url, game)
         VALUES (?, ?, ?, ?, ?, ?, '', ?, ?, 'pokemon')`,
        [`${PREFIX}${s.id}`, s.name, s.series, s.printed_total, s.total, s.release_date, s.symbol_url, s.logo_url]
      );
    }
    console.log(`Cached ${sets.length} Korean sets.`);
  } catch (error) {
    console.error('tcgexchange set sync:', error.message);
  }
}

// Price sweep: tcgexchange has no prices. TCGCSV can price Korean cards off the
// English catalogue (tcgcsvApi already handles non-English languages), so this
// is a no-op that keeps the interface consistent.
async function updateCollectionPrices() { /* no prices from tcgexchange */ }

module.exports = {
  client, listSets, getCardsBySet, searchCards, getCardById, findPrinting,
  fetchAndCacheSets, updateCollectionPrices, normalizeCard, cardId, providerId, splitId,
  BUNDLE_PATH,
};
